import java.util.List;

// Decides, for a new post, whether to proactively fan out to every follower's
// feed cache or skip that step for celebrity accounts whose follower count
// would make proactive fan out prohibitively expensive.
public class FeedFanoutService {
    private static final int CELEBRITY_THRESHOLD = 1_000_000;
    private final FollowGraphClient followGraph;
    private final FeedCacheClient feedCache;

    public FeedFanoutService(FollowGraphClient followGraph, FeedCacheClient feedCache) {
        this.followGraph = followGraph;
        this.feedCache = feedCache;
    }

    public void handleNewPost(String authorId, String postId, int authorFollowerCount) {
        if (authorFollowerCount >= CELEBRITY_THRESHOLD) {
            // Celebrity account: skip proactive push, rely on read time merge.
            return;
        }
        List<String> followers = followGraph.getFollowers(authorId);
        for (String followerId : followers) {
            feedCache.pushToFeed(followerId, postId);
        }
    }

    public interface FollowGraphClient {
        List<String> getFollowers(String userId);
    }

    public interface FeedCacheClient {
        void pushToFeed(String userId, String postId);
    }
}

