import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Buffers like increments in memory and periodically flushes accumulated
// counts to the database, avoiding a write per individual like tap.
public class LikeCounterAggregator {
    private final Map<String, Integer> pendingIncrements = new ConcurrentHashMap<>();

    public void recordLike(String postId) {
        pendingIncrements.merge(postId, 1, Integer::sum);
    }

    public void flush(PostDatabase db) {
        for (Map.Entry<String, Integer> entry : pendingIncrements.entrySet()) {
            db.incrementLikeCount(entry.getKey(), entry.getValue());
        }
        pendingIncrements.clear();
    }

    public interface PostDatabase {
        void incrementLikeCount(String postId, int amount);
    }
}

