#include <map>
#include <string>

struct PostDatabase {
    virtual void incrementLikeCount(const std::string& postId, int amount) = 0;
    virtual ~PostDatabase() = default;
};

// Buffers like increments in memory and periodically flushes accumulated
// counts to the database, avoiding a write per individual like tap.
class LikeCounterAggregator {
public:
    void recordLike(const std::string& postId) { pendingIncrements_[postId]++; }

    void flush(PostDatabase& db) {
        for (auto& [postId, amount] : pendingIncrements_) db.incrementLikeCount(postId, amount);
        pendingIncrements_.clear();
    }

private:
    std::map<std::string, int> pendingIncrements_;
};

