from typing import Dict, Protocol


class PostDatabase(Protocol):
    def increment_like_count(self, post_id: str, amount: int) -> None: ...


# Buffers like increments in memory and periodically flushes accumulated
# counts to the database, avoiding a write per individual like tap.
class LikeCounterAggregator:
    def __init__(self):
        self._pending_increments: Dict[str, int] = {}

    def record_like(self, post_id: str) -> None:
        self._pending_increments[post_id] = self._pending_increments.get(post_id, 0) + 1

    def flush(self, db: PostDatabase) -> None:
        for post_id, amount in self._pending_increments.items():
            db.increment_like_count(post_id, amount)
        self._pending_increments.clear()

